            const slider=document.createElement('input');slider.type='range';slider.min=String(min);slider.max=String(max);slider.step=String(step);slider.value=String(dockConf[key]);
            slider.addEventListener('input',()=>{dockConf[key]=Number(slider.value);label.textContent=`${title}: ${fmt(dockConf[key])}`;essentialsSave();mobileApplyDockAppearance(true);});
