        perf.append(prow,essentialsH('p',`Last sample: ${essentialsBudgetLastFps||'—'} FPS · Current mode: ${getFeatureSettings().performanceMode}`,{fontSize:'12px',color:getExtensionsStyle().muted}));container.append(perf);
