        veil.style.cssText='position:fixed;inset:0;z-index:2147483600;background:#0009;display:flex;align-items:center;justify-content:center;padding:8px;box-sizing:border-box;';
        veil.addEventListener('pointerdown',e=>e.stopPropagation());
