        sheet.style.cssText='box-sizing:border-box;width:min(520px,100%);max-height:calc(100dvh - 16px);display:flex;flex-direction:column;overflow:hidden;border:2px solid #9e80ba;border-radius:12px;background:#241b30;color:#fff;font:15px Arial,sans-serif;box-shadow:0 8px 28px #000d;';
        sheet.style.fontSize=`${Math.max(13,subbyUiSize(15))}px`;
        const heading=document.createElement('header');heading.style.cssText='padding:10px;display:flex;gap:8px;align-items:center;justify-content:space-between;background:#392746;flex:0 0 auto;';
        const t=document.createElement('strong');t.textContent=title;
        const close=document.createElement('button');close.type='button';close.textContent='✕ Close';close.addEventListener('click',mobileCloseDialog);
        heading.append(t,close);sheet.append(heading);
