        sheet.append(body);veil.append(sheet);document.body.append(veil);mobileDockDialog=veil;
        Object.assign(veil.style,{padding:'max(6px, env(safe-area-inset-top)) max(6px, env(safe-area-inset-right)) max(6px, env(safe-area-inset-bottom)) max(6px, env(safe-area-inset-left))'});
