            notice.style.cssText='color:#d6c3e2;margin:0 0 10px;font-size:13px;';body.append(notice);
            const search=document.createElement('input');search.placeholder='Search plushies…';search.type='search';
            search.style.cssText='width:100%;box-sizing:border-box;min-height:46px;border-radius:8px;padding:8px;margin-bottom:10px;border:1px solid #a78ac0;background:#160f1e;color:white;font:16px Arial;';
            body.append(search);
